12	 */
13	public abstract class Organism extends FieldOccupant implements Actor
14	{
15	    // Whether the organism is alive or not
16	    private boolean alive;
17	    // The water level of the organism
18	    private int waterLevel;
19	    // Whether the organism is infected with a disease or not.
20	    private boolean infected;
21	    // The organism's age
22	    private int age;
23	
24	    /**
25	     * Constructor for organisms - places new organism in location
26	     *
27	     * @param randomAge If true, the organism will have random age
28	     * @param field The field currently occupied.
29	     * @param location The location within the field.
30	     */
31	    public Organism(boolean randomAge, Field field, Location location)
32	    {
33	        super(field, location);
34	        alive = true;
35	        age = 0;
36	    }
37	    
38	     /**
39	     * Make this organism act - that is: make it do
40	     * whatever it wants/needs to do.
41	     * All organisms will age and lose water with each step that they act
42	     *
43	     * @param newOrganisms A list to receive newly born organisms
44	     */
45	    public void act(List<Actor> newOrganisms)
46	    {
47	        incrementAge();
48	        decreaseWaterLevel();
49	    }
50	    
51	    /**
52	     * Check whether the organism is alive or not.
53	     * @return true if the organism is still alive.
54	     */
55	    protected boolean isAlive()
56	    {
57	        return alive;
58	    }
59	
60	    /**
61	     * Indicate that the organism is no longer alive.
62	     * It is removed from the field.
63	     */
64	    public void setDead()
65	    {
66	        alive = false;
67	        clearFromField();
68	    }
69	    
70	    /**
71	     * Increase the age.
72	     */
73	    public void incrementAge()
74	    {
75	        age = age + 1;
76	    }
77	    
78	    /**
79	     * @return The value that eating this organism gives predator
80	     */
81	    abstract public int getFoodValue();
82	    
83	    /**
84	     * Look for water adjacent to the organism's current location
85	     * @return Where water was found, or null if it wasn't 
86	     */
87	    protected Location findWater() {
88	        Field field = getField();
89	        List<Location> adjacent = field.adjacentLocations(getLocation());
90	        Iterator<Location> it = adjacent.iterator();
91	        while(it.hasNext()){
92	            Location where = it.next();
93	            Object waterSource = field.getObjectAt(where);
94	            if(waterSource instanceof Lake) {
95	                Lake lake = (Lake) waterSource;
96	                // if there is enough water left to drink
97	                if(lake.getVolume() >= lake.getWaterValue()){
98	                    // increase drinking organism's water level and reduces lake's water level
99	                    int newWaterLevel = getWaterLevel() + lake.getWaterValue();
100	                    this.setWaterLevel(newWaterLevel);
101	                    lake.reduceVolume(lake.getWaterValue());
102	                    return where;
103	                }
104	                // if only a little bit of water left to drink, drinks remnants 
105	                // then empties lake
106	                else if (lake.getVolume() >= 0) {
107	                    int newWaterLevel = getWaterLevel() + lake.getVolume();
108	                    this.setWaterLevel(newWaterLevel);
109	                    lake.setVolume(0);
110	                    lake.setDead();
111	                    return where;
112	                }
113	                else if(lake.getVolume() <=0){
114	                    lake.setDead();
115	                    return null;
116	                }
117	            }
118	        }
119	        return null;
120	    }
121	    
122	    /** 
123	     * Lower's the organism's water level - may result in its death
124	     */
125	    public void decreaseWaterLevel(){
126	        int newWaterLevel = getWaterLevel() - 1;
127	        setWaterLevel(newWaterLevel);
128	        if(getWaterLevel() <=0) {
129	            setDead();
130	        }
131	    }
132	    
