150	     * @param age The current age of the organism
151	     */
152	    protected void setAge(int age)
153	    {
154	        this.age = age;
155	    }
156	    
157	    /**
158	     * @return Current age of the organism
159	     */
160	    protected double getAge()
161	    { 
162	        return age;
163	    }
164	    
165	    /**
166	     * Infects the organism with a disease
167	     */
168	    protected void setInfected() {
169	        infected = true;
170	    }
171	    
172	    /** 
