import java.util.ArrayList;

/** Headless check of the unified disease-infection lifecycle. */
public class InfectionTest
{
    public static void main(String[] args)
    {
        Field field = new Field(10, 10);
        Lion lion = new Lion(false, field, new Location(0, 0));
        Lake lake = new Lake(false, field, new Location(5, 5));

        // 1) Unified infection state works on both occupant types via FieldOccupant.
        boolean startClear = !lion.isInfected() && !lake.isInfected();
        lion.setInfected();
        lake.setInfected();
        boolean infected = lion.isInfected() && lake.isInfected();

        // 2) Run the infection to full term through Disease.act():
        //    an organism should die; a water source should be cured.
        Leptospirosis disease = new Leptospirosis(field);   // duration 10; affects Lion & Lake
        disease.addIndividual(lion);
        disease.addIndividual(lake);
        for (int i = 0; i < 11; i++) {
            disease.act(new ArrayList<Actor>());
        }
        boolean organismDied = !lion.isAlive();
        boolean waterCured = !lake.isInfected();

        System.out.println("startClear:" + startClear + " infected:" + infected
            + " organismDied:" + organismDied + " waterCured:" + waterCured);
        System.out.println((startClear && infected && organismDied && waterCured)
            ? "PASS: infect/spread/expire unified across Organism, WaterSources, Disease."
            : "FAIL");
    }
}

